// Query: *[_type == "series" && slug.current == $slug][0] {    _id, title, "slug": slug.current, description, status,    "posts": *[_type == "post" && references(^._id) && defined(slug.current)] | order(seriesOrder asc, publishedAt asc) {   _id,  title,  "slug": slug.current,  publishedAt,  excerpt,  "imageUrl": mainImage.asset->url,  "lqip": mainImage.asset->metadata.lqip,  "categories": categories[]->title,  "tags": tags[]->{ _id, title, "slug": slug.current },  articleType,  // The card carries the small status mark (Phase 3.3). Without this the index and the  // feeds had no status at all while the article had three tiers of it.  reviewStatus,  // 3.7 + 3B. The newest date across the changelog AND the corrections -- both are material  // revisions. Projected as one value rather than the whole arrays: the card needs the date  // and the kinds, not twenty revision notes per card.  // coalesce(..., []) because null + array is null in GROQ -- and a backtick in this  // comment would end the template literal the query lives in, which is how the first  // version of this line silently dropped 27 of 40 queries from typegen.  // A post with a changelog and no corrections would otherwise project no date at all.  "lastRevised": (coalesce(changelog[].date, []) + coalesce(corrections[].date, [])) | order(@ desc)[0],  "correctionKinds": corrections[].kind,    "wordCount": coalesce(math::sum(body[_type == "block" && defined(children)]{    "w": length(string::split(array::join(children[].text, ""), " "))  }.w), 0),  "series": series->{ title, "slug": slug.current }, seriesOrder }  }
export type SeriesBySlugQueryResult = {
  _id: string
  title: string | null
  slug: string | null
  description: string | null
  status: 'complete' | 'in-progress' | 'paused' | null
  posts: Array<{
    _id: string
    title: string | null
    slug: string | null
    publishedAt: string | null
    excerpt: string | null
    imageUrl: string | null
    lqip: string | null
    categories: Array<string | null> | null
    tags: Array<{
      _id: string
      title: string | null
      slug: string | null
    }> | null
    articleType: 'concept-deep-dive' | 'lab-notes' | 'perspective' | null
    reviewStatus: Array<string> | null
    lastRevised: null | string
    correctionKinds: Array<'clarification' | 'correction' | 'update' | null> | null
    wordCount: number | 0
    series: {
      title: string | null
      slug: string | null
    } | null
    seriesOrder: number | null
  }>
} | null

